module cache_ram (
	clk_i,
	addr_i,
	wren_i,
	wdata_i,
	q_o
);
	parameter ADDR_WIDTH = 7;
	parameter DATA_WIDTH = 32;
	parameter MEM_INIT_FILE = " ";
	parameter SIM_INIT_FILE = " ";
	parameter DEVICE_FAMILY = "Cyclone V";
	parameter LPM_HINT = "ENABLE_RUNTIME_MOD=NO";
	input wire clk_i;
	input wire [ADDR_WIDTH - 1:0] addr_i;
	input wire wren_i;
	input wire [DATA_WIDTH - 1:0] wdata_i;
	output wire [DATA_WIDTH - 1:0] q_o;
	localparam NUM_WORDS = 1 << ADDR_WIDTH;
	reg [DATA_WIDTH - 1:0] q_out;
	reg [DATA_WIDTH - 1:0] mem_q [0:NUM_WORDS - 1];
	integer init_i;
	always @(posedge clk_i) begin
		if (wren_i)
			mem_q[addr_i] <= wdata_i;
		q_out <= mem_q[addr_i];
	end
	assign q_o = q_out;
endmodule
module cache_ram_dp (clk_i, addr_a_i, wren_a_i, wdata_a_i, q_a_o, addr_b_i, wren_b_i, wdata_b_i, q_b_o);
	parameter ADDR_WIDTH = 7;
	parameter DATA_WIDTH = 8;
	parameter MEM_INIT_FILE = " ";
	parameter SIM_INIT_FILE = " ";
	parameter DEVICE_FAMILY = "Cyclone V";
	input wire clk_i;
	input wire [ADDR_WIDTH - 1:0] addr_a_i;
	input wire wren_a_i;
	input wire [DATA_WIDTH - 1:0] wdata_a_i;
	output reg [DATA_WIDTH - 1:0] q_a_o;
	input wire [ADDR_WIDTH - 1:0] addr_b_i;
	input wire wren_b_i;
	input wire [DATA_WIDTH - 1:0] wdata_b_i;
	output reg [DATA_WIDTH - 1:0] q_b_o;
	(* ram_style = "distributed" *) reg [DATA_WIDTH - 1:0] mem_q [0:(1 << ADDR_WIDTH) - 1];
	wire [ADDR_WIDTH - 1:0] wa = wren_b_i ? addr_b_i : addr_a_i;
	wire [DATA_WIDTH - 1:0] wd = wren_b_i ? wdata_b_i : wdata_a_i;
	always @(posedge clk_i) begin
		if (wren_a_i || wren_b_i)
			mem_q[wa] <= wd;
		q_a_o <= mem_q[addr_a_i];
		q_b_o <= mem_q[addr_b_i];
	end
endmodule
