	reg [31:0] address_offset;
	wire [2:0] cart_cs_reg;
	wire [2:0] cart_cs_reg_m;
	reg [7:0] bank_mask;
	reg [16:0] ram_mask;
	reg [7:0] XCTRL1;
	wire [7:0] XCTRL2;
	wire [7:0] XCTRL3;
	wire [7:0] XCTRL4;
	wire [7:0] XCTRL5;
	wire souper_ram_cs;
	wire [24:0] souper_addr;
