			bank_type <= 3'd0;
			address_offset <= 32'd0;
			bank_mask <= 8'b11111111;
			ram_mask <= 1'sb1;
			bs_map <= 9'd0;
			if (is_ace) begin
				hardware_map <= 48'h0006db924924;
				bank_map <= {82'h000000000000000000004, ace_a[5:0], 10'h00c, ace_c[5:0], 1'd0, ace_d[6:0], 2'd0, ace_e[5:0], 8'd7};
				bank_type <= 3'd5;
			end
			else if (cart_flags[8]) begin
				hardware_map <= 48'h000924924924;
				bank_map <= 128'h000000000d0d0c0c0f0f000000000e0e;
				bank_map[40+:8] <= {bank_reg[2:0], 1'b0};
				bank_map[32+:8] <= {bank_reg[2:0], 1'b0};
				bank_map[24+:8] <= {bank_reg[2:0], 1'b1};
				bank_map[16+:8] <= {bank_reg[2:0], 1'b1};
				bank_type <= 3'd1;
			end
			else if (cart_flags[9]) begin
				hardware_map <= 48'h000924924924;
				bank_map <= 128'h00000000000000000202020203030303;
				bank_map[88+:8] <= {3'b000, bank_reg[1]};
				bank_map[80+:8] <= {3'b000, bank_reg[1]};
				bank_map[72+:8] <= {3'b000, bank_reg[1]};
				bank_map[64+:8] <= {3'b000, bank_reg[1]};
				bank_type <= 3'd3;
			end
			else if (cart_flags[12]) begin
				hardware_map <= 48'h924924924924;
				bank_type <= 3'd4;
			end
			else if (((cart_flags[13] || cart_flags[14]) || cart_flags[1]) || (cart_size_bs >= 32'h00010000)) begin
				hardware_map <= 48'h000924924924;
				bank_map <= {32'h00000000, second_highest_bank, second_highest_bank, second_highest_bank, second_highest_bank, 32'h00000000, highest_bank, highest_bank, highest_bank, highest_bank};
				bank_map[56+:8] <= sg_bank;
				bank_map[48+:8] <= sg_bank;
				bank_map[40+:8] <= sg_bank;
				bank_map[32+:8] <= sg_bank;
				if (is_bankset && (cart_size_bs == 32'h00008000)) begin
					bank_mask <= 8'b00000001;
					bs_map <= 9'b000000010;
					bank_map[56+:8] <= 8'd0;
					bank_map[48+:8] <= 8'd0;
					bank_map[40+:8] <= 8'd0;
					bank_map[32+:8] <= 8'd0;
				end
				else if (is_bankset && (cart_size_bs == 32'h0000c000)) begin
					bank_mask <= 8'b00000011;
					bs_map <= 9'b000000011;
					bank_map[88+:8] <= 8'd0;
					bank_map[80+:8] <= 8'd0;
					bank_map[72+:8] <= 8'd0;
					bank_map[64+:8] <= 8'd0;
					bank_map[56+:8] <= 8'd1;
					bank_map[48+:8] <= 8'd1;
					bank_map[40+:8] <= 8'd1;
					bank_map[32+:8] <= 8'd1;
				end
				else if (is_bankset_52k) begin
					hardware_map[36+:3] <= 3'd4;
					bank_map[96+:8] <= 8'd0;
					bank_map[88+:8] <= 8'd1;
					bank_map[80+:8] <= 8'd1;
					bank_map[72+:8] <= 8'd1;
					bank_map[64+:8] <= 8'd1;
					bank_map[56+:8] <= 8'd2;
					bank_map[48+:8] <= 8'd2;
					bank_map[40+:8] <= 8'd2;
					bank_map[32+:8] <= 8'd2;
					bank_map[24+:8] <= 8'd3;
					bank_map[16+:8] <= 8'd3;
					bank_map[8+:8] <= 8'd3;
					bank_map[0+:8] <= 8'd3;
				end
				else if (cart_size_bs[22]) begin
					bank_mask <= 8'b11111111;
					bs_map <= 9'b100000000;
				end
