	p1_mclk,
	m0_mclk,
	m1_mclk,
	bl_mclk
);
	input wire clk;
	input wire reset;
	input wire [4:0] hclk;
	input wire [4:0] oclk;
	input wire [4:0] pclk;
	input wire hmove;
	input wire hblank;
	input wire [3:0] p0_m;
	input wire [3:0] p1_m;
	input wire [3:0] m0_m;
	input wire [3:0] m1_m;
	input wire [3:0] bl_m;
	output wire sec;
	output wire p0_mclk;
	output wire p1_mclk;
	output wire m0_mclk;
	output wire m1_mclk;
	output wire bl_mclk;
	reg [1:0] p0ec;
	reg [1:0] p1ec;
	reg [1:0] m0ec;
	reg [1:0] m1ec;
	reg [1:0] blec;
	reg [3:0] hmove_cnt;
	wire sec_1;
	wire sec_0;
	wire hmove_latch;
	wire [3:0] hmc_uns = {~hmove_cnt[3], hmove_cnt[2:0]};
	assign p0_mclk = p0ec[1] && hclk[2];
	assign p1_mclk = p1ec[1] && hclk[2];
	assign m0_mclk = m0ec[1] && hclk[2];
	assign m1_mclk = m1ec[1] && hclk[2];
	assign bl_mclk = blec[1] && hclk[2];
