	input wire RESET;
	output reg [7:0] PLAYBACK;
	input wire [2:0] PALETTE;
	input wire [7:0] d_in;
	input wire WM;
	input wire border;
	input wire latch_byte;
	input wire latch_hpos;
	input wire [199:0] COLOR_MAP;
	input wire [1:0] RM;
	input wire KANGAROO_MODE;
	input wire BORDER_CONTROL;
	input wire COLOR_KILL;
	input wire lrc;
	input wire mclk0;
	input wire mclk1;
	input wire cram_write;
	localparam signed [31:0] ROWS = 40;
	reg wr_buf;
	reg [63:0] written [0:1][0:3];
	reg [2:0] playback_palette;
	reg [1:0] playback_color;
	reg [4:0] playback_cell;
	reg [8:0] playback_ix;
	reg [7:0] lram_ix;
	reg [7:0] hpos;
	reg [19:0] cell_data;
	reg [3:0] cell_wr;
	reg [7:0] bank_sel;
	reg [23:0] bank_row;
	reg [19:0] bank_data;
	reg [3:0] bank_wr;
	wire [19:0] bank_q;
	wire [19:0] bank_unused;
