	wire swap_now = (~RESET & mclk0) & lrc;
	wire wr_buf_next = (swap_now ? ~wr_buf : wr_buf);
	wire [8:0] playback_ix_next = (mclk0 ? (border ? 9'd0 : playback_ix + 9'd1) : playback_ix);
	wire [7:0] lram_ix_next = playback_ix_next[8:1];
	wire [5:0] rd_row = lram_ix[7:2];
	function automatic signed [5:0] sv2v_cast_6_signed;
		input reg signed [5:0] inp;
		sv2v_cast_6_signed = inp;
	endfunction
	wire cell_present = (rd_row < sv2v_cast_6_signed(ROWS)) && written[~wr_buf][lram_ix[1:0]][rd_row];
	wire [4:0] cell_read = (cell_present ? bank_q[lram_ix[1:0] * 5+:5] : 5'd0);
	wire [47:0] pb_map_index;
	assign pb_map_index = 40'h00cc963e55;
	always @(posedge clk_sys) begin
		if (mclk0) begin
			if (~border)
				playback_ix <= playback_ix + 1'd1;
			else
				playback_ix <= 0;
		end
		if (mclk0) begin
			if ((playback_color == 2'b00) || border)
				PLAYBACK <= (border & ~BORDER_CONTROL ? 8'd0 : COLOR_MAP[0+:8]);
			else
				PLAYBACK <= COLOR_MAP[(pb_map_index[(7 - playback_palette) * 6+:6] + playback_color) * 8+:8];
		end
	end
	always @(*) begin
		if (_sv2v_0)
			;
		lram_ix = playback_ix[8:1];
		playback_cell = cell_read;
		playback_palette = playback_cell[4:2];
		playback_color = playback_cell[1:0];
		casex (RM)
			2'b0x: begin
				playback_palette = playback_cell[4:2];
				playback_color = playback_cell[1:0];
			end
			2'b10: begin
				playback_palette = {playback_cell[4], 2'b00};
				if (playback_ix[0])
					playback_color = {playback_cell[0], playback_cell[2]};
				else
					playback_color = {playback_cell[1], playback_cell[3]};
			end
			2'b11: begin
				playback_palette = playback_cell[4:2];
				if (playback_ix[0])
					playback_color = {playback_cell[0], 1'b0};
				else
					playback_color = {playback_cell[1], 1'b0};
			end
		endcase
	end
	always @(*) begin
		if (_sv2v_0)
			;
		begin : sv2v_autoblock_1
			reg signed [31:0] j;
			for (j = 0; j < 4; j = j + 1)
				begin
					cell_data[j * 5+:5] = 5'd0;
					cell_wr[j] = 1'b0;
				end
		end
		case (WM)
			1'b0: begin
				cell_wr[0] = |d_in[7:6] || KANGAROO_MODE;
				cell_data[0+:5] = {PALETTE, d_in[7:6]};
				cell_wr[1] = |d_in[5:4] || KANGAROO_MODE;
				cell_data[5+:5] = {PALETTE, d_in[5:4]};
				cell_wr[2] = |d_in[3:2] || KANGAROO_MODE;
				cell_data[10+:5] = {PALETTE, d_in[3:2]};
				cell_wr[3] = |d_in[1:0] || KANGAROO_MODE;
				cell_data[15+:5] = {PALETTE, d_in[1:0]};
			end
			1'b1: begin
				cell_wr[0] = |d_in[7:6] || KANGAROO_MODE;
				cell_data[0+:5] = {PALETTE[2], d_in[3:2], d_in[7:6]};
				cell_wr[1] = |d_in[5:4] || KANGAROO_MODE;
				cell_data[5+:5] = {PALETTE[2], d_in[1:0], d_in[5:4]};
			end
		endcase
	end
	always @(posedge clk_sys)
		if (RESET)
			hpos <= 8'd0;
		else if (mclk0) begin
			if (latch_hpos)
				hpos <= d_in;
			if (latch_byte)
				hpos <= hpos + (WM ? 8'd2 : 8'd4);
		end
	function automatic signed [1:0] sv2v_cast_2_signed;
		input reg signed [1:0] inp;
		sv2v_cast_2_signed = inp;
	endfunction
	function automatic [7:0] sv2v_cast_8;
		input reg [7:0] inp;
		sv2v_cast_8 = inp;
	endfunction
	function automatic [5:0] sv2v_cast_6;
		input reg [5:0] inp;
		sv2v_cast_6 = inp;
	endfunction
	always @(*) begin
		if (_sv2v_0)
			;
		begin : sv2v_autoblock_2
			reg signed [31:0] b;
			for (b = 0; b < 4; b = b + 1)
				begin
					bank_sel[b * 2+:2] = sv2v_cast_2_signed(b) - hpos[1:0];
					bank_row[b * 6+:6] = sv2v_cast_6((hpos + sv2v_cast_8(bank_sel[b * 2+:2])) >> 2);
					bank_data[b * 5+:5] = cell_data[bank_sel[b * 2+:2] * 5+:5];
					bank_wr[b] = byte_now && cell_wr[bank_sel[b * 2+:2]];
				end
		end
	end
	always @(posedge clk_sys) begin
		wr_buf <= wr_buf_next;
		begin : sv2v_autoblock_3
			reg signed [31:0] b;
			for (b = 0; b < 4; b = b + 1)
				begin
					if (swap_now)
						written[wr_buf_next][b] <= 64'd0;
					if (bank_wr[b])
						written[wr_buf_next][b][bank_row[b * 6+:6]] <= 1'b1;
				end
		end
	end
	genvar _gv_b_1;
	generate
		for (_gv_b_1 = 0; _gv_b_1 < 4; _gv_b_1 = _gv_b_1 + 1) begin : bank
			localparam b = _gv_b_1;
			cache_ram_dp #(
				.ADDR_WIDTH(7),
				.DATA_WIDTH(5)
			) cells(
				.clk_i(clk_sys),
				.addr_a_i({wr_buf_next, bank_row[b * 6+:6]}),
				.wren_a_i(bank_wr[b]),
				.wdata_a_i(bank_data[b * 5+:5]),
				.q_a_o(bank_unused[b * 5+:5]),
				.addr_b_i({~wr_buf_next, lram_ix_next[7:2]}),
				.wren_b_i(1'b0),
				.wdata_b_i(5'd0),
				.q_b_o(bank_q[b * 5+:5])
			);
		end
	endgenerate
	initial _sv2v_0 = 0;
endmodule
