module mos6502_dp (
	clk_sys,
	phi1_en,
	phi2_en,
	c,
	ir,
	data_in,
	a,
	x,
	y,
	s,
	p,
	dl,
	addr_out,
	data_out,
	acr_now,
	pcl,
	pch
);
	reg _sv2v_0;
	parameter [0:0] BCD_EN = 1'b1;
	input wire clk_sys;
	input wire phi1_en;
	input wire phi2_en;
	input wire [75:0] c;
	input wire [7:0] ir;
	input wire [7:0] data_in;
	output reg [7:0] a;
	output reg [7:0] x;
	output reg [7:0] y;
	output wire [7:0] s;
	output wire [7:0] p;
	output reg [7:0] dl;
	output wire [15:0] addr_out;
	output wire [7:0] data_out;
	output wire acr_now;
	output reg [7:0] pcl;
	output reg [7:0] pch;
	reg [7:0] s_in;
	reg [7:0] s_out;
	reg [7:0] pcls;
	reg [7:0] pchs;
	reg [7:0] abl;
	reg [7:0] abh;
	reg [7:0] dor;
	reg [7:0] ai;
	reg [7:0] bi;
	reg [7:0] add;
	reg acr;
	reg avr;
	reg p_n;
	reg p_v;
	reg p_d;
	reg p_i;
	reg p_z;
	reg p_c;
	wire [7:0] p_out;
	reg [7:0] db;
	reg [7:0] sb;
	reg [7:0] adl;
	reg [7:0] adh;
	reg [7:0] db_raw;
	reg [7:0] sb_raw;
	reg [7:0] adh_raw;
	always @(*) begin
		if (_sv2v_0)
			;
		db_raw = 8'hff;
		if (c[75])
			db_raw = db_raw & dl;
		if (c[72])
			db_raw = db_raw & pcl;
		if (c[70])
			db_raw = db_raw & pch;
		if (c[63])
			db_raw = db_raw & a;
		if (c[59])
			db_raw = db_raw & p_out;
	end
	always @(*) begin
		if (_sv2v_0)
			;
		sb_raw = 8'hff;
		if (c[68])
			sb_raw = sb_raw & s_out;
		if (c[66])
			sb_raw = sb_raw & x;
		if (c[65])
			sb_raw = sb_raw & y;
		if (c[64])
			sb_raw = sb_raw & a;
		if (c[62])
			sb_raw[6:0] = sb_raw[6:0] & add[6:0];
		if (c[61])
			sb_raw[7] = sb_raw[7] & add[7];
	end
	always @(*) begin
		if (_sv2v_0)
			;
		adl = 8'hff;
		if (c[74])
			adl = adl & dl;
		if (c[71])
			adl = adl & pcl;
		if (c[67])
			adl = adl & s_out;
		if (c[60])
			adl = adl & add;
		if (c[58])
			adl[0] = 1'b0;
		if (c[57])
			adl[1] = 1'b0;
		if (c[56])
			adl[2] = 1'b0;
	end
	always @(*) begin
		if (_sv2v_0)
			;
		adh_raw = 8'hff;
		if (c[73])
			adh_raw = adh_raw & dl;
		if (c[69])
			adh_raw = adh_raw & pch;
		if (c[55])
			adh_raw[0] = 1'b0;
		if (c[54])
			adh_raw[7:1] = 7'b0000000;
	end
	always @(*) begin : sv2v_autoblock_1
		reg [7:0] merged;
		if (_sv2v_0)
			;
		merged = sb_raw;
		if (c[53])
			merged = merged & db_raw;
		if (c[52])
			merged = merged & adh_raw;
		sb = merged;
		db = (c[53] ? merged : db_raw);
		adh = (c[52] ? merged : adh_raw);
	end
	wire [7:0] alu_res;
	wire [7:0] a_next;
	wire alu_acr;
	wire alu_avr;
	wire alu_hc;
	wire alu_active;
	assign alu_active = (((c[33] | c[32]) | c[31]) | c[30]) | c[29];
	reg hc_held;
	mos6502_alu #(.BCD_EN(BCD_EN)) alu(
		.ai(ai),
		.bi(bi),
		.cin(c[28]),
		.sums(c[33]),
		.ands(c[32]),
		.eors(c[31]),
		.ors(c[30]),
		.srs(c[29]),
		.daa(c[27]),
		.res(alu_res),
		.acr(alu_acr),
		.avr(alu_avr),
		.hc(alu_hc)
	);
	wire [7:0] daa_out;
	mos6502_daa #(.BCD_EN(BCD_EN)) adjust(
		.sb(sb),
		.daa(c[27]),
		.dsa(c[26]),
		.hc(hc_held),
		.acr(acr),
		.out(daa_out)
	);
	reg arr_lo_q;
	reg arr_hi_q;
	reg [7:0] arr_fix;
	always @(*) begin
		if (_sv2v_0)
			;
