		if (arr_lo_q)
			arr_fix[3:0] = sb[3:0] + 4'd6;
		if (arr_hi_q)
			arr_fix[7:4] = sb[7:4] + 4'd6;
	end
	assign a_next = (c[23] ? arr_fix : daa_out);
	wire pc_carry;
	wire [7:0] pcl_next;
	wire [7:0] pch_next;
	assign {pc_carry, pcl_next} = {1'b0, pcls} + {8'b00000000, c[22]};
	assign pch_next = pchs + {7'b0000000, pc_carry};
	assign p = {p_n, p_v, 2'b00, p_d, p_i, p_z, p_c};
	assign p_out = {p_n, p_v | c[10], 1'b1, c[1], p_d, p_i, p_z, p_c};
	always @(posedge clk_sys) begin
		if (phi1_en) begin
			if (c[51])
				x <= sb;
			if (c[50])
				y <= sb;
			if (c[45])
				a <= a_next;
			if (c[49])
				s_in <= sb;
			else if (c[47])
				s_in <= s_out + 8'd1;
			else if (c[46])
				s_in <= s_out - 8'd1;
			if (c[44])
				ai <= sb;
			if (c[43])
				ai <= 8'h00;
			if (c[42])
				bi <= db;
			if (c[41])
				bi <= ~db;
			if (c[40])
				bi <= adl;
			if (c[39])
				pcls <= adl;
			else
				pcls <= pcl;
			if (c[37])
				pchs <= adh;
			else
				pchs <= pch;
			if (c[35])
				abl <= adl;
			if (c[34])
				abh <= adh;
			dor <= db;
			if (c[10])
				p_v <= 1'b1;
			if (c[2]) begin
				p_z <= db[1];
				p_i <= db[2];
				p_d <= db[3];
			end
			if (c[21])
				p_c <= db[0];
			if (c[20])
				p_c <= ir[5];
			if (c[19])
				p_c <= acr;
			if (c[18])
				p_n <= db[7];
			if (c[17])
				p_z <= db == 8'h00;
			if (c[16])
				p_i <= ir[5];
			if (c[7])
				p_i <= 1'b1;
			if (c[15])
				p_d <= ir[5];
			if (c[14])
				p_v <= db[6];
			if (c[9])
				p_c <= db[7];
			if (c[8]) begin
				p_c <= (c[23] ? arr_hi_q : db[6]);
				p_v <= db[6] ^ db[5];
			end
			if (c[13])
				p_v <= avr;
			if (c[12])
				p_v <= 1'b1;
			if (c[11])
				p_v <= 1'b0;
		end
		if (phi2_en) begin
			if (c[24]) begin
				arr_lo_q <= (ai[3:0] & bi[3:0]) >= 4'd5;
				arr_hi_q <= (ai[7:4] & bi[7:4]) >= 4'd5;
			end
			if (c[25])
				add <= 8'hff;
			else if (alu_active) begin
				add <= alu_res;
				acr <= alu_acr;
				avr <= alu_avr;
				hc_held <= alu_hc;
			end
			dl <= data_in;
			if (c[6])
				p_n <= alu_res[7];
			if (c[5])
				p_z <= alu_res == 8'h00;
			if (c[4])
				p_c <= alu_acr;
			if (c[3])
				p_v <= alu_avr;
			pcl <= pcl_next;
			pch <= pch_next;
			s_out <= (c[48] ? s_out : s_in);
		end
	end
	assign acr_now = alu_acr;
	assign s = s_out;
	assign addr_out = {abh, abl};
	assign data_out = dor;
	initial _sv2v_0 = 0;
endmodule
