module pokey_bus (
	clk,
	pre_s01,
	phi2b,
	a,
	cs0_n,
	cs1,
	rw,
	d_in,
	read_bus_n,
	d_out,
	d_oe,
	write_data,
	addr_rd,
	addr_wr,
	addr_wr_n,
	stimer_strobe,
	skres_strobe,
	potgo_strobe
);
	reg _sv2v_0;
	input wire clk;
	input wire pre_s01;
	input wire phi2b;
	input wire [3:0] a;
	input wire cs0_n;
	input wire cs1;
	input wire rw;
	input wire [7:0] d_in;
	input wire [7:0] read_bus_n;
	output wire [7:0] d_out;
	output wire d_oe;
	output wire [7:0] write_data;
	output wire [15:0] addr_rd;
	output wire [15:0] addr_wr;
	output wire [15:0] addr_wr_n;
	output wire stimer_strobe;
	output wire skres_strobe;
	output wire potgo_strobe;
	reg [3:0] a_q;
	always @(posedge clk)
		if (pre_s01)
			a_q <= a;
	wire [3:0] ba = a_q;
	wire [3:0] na = ~a_q;
	wire cs_rd = ~((~rw | cs0_n) | ~cs1);
	wire cs_wr_n = ~((~rw & ~cs0_n) & cs1);
	reg [15:0] row_match;
	reg [3:0] taps;
	reg [3:0] rv;
	always @(*) begin
		if (_sv2v_0)
			;
		row_match = 16'd0;
		rv = 4'd0;
		begin : sv2v_autoblock_1
			reg signed [31:0] r;
			for (r = 0; r < 16; r = r + 1)
				begin
					taps = (ba & ~rv) | (na & rv);
					row_match[r] = ~|taps;
					rv = rv + 4'd1;
				end
		end
	end
	localparam [15:0] RD_ROWS = 16'he7ff;
	localparam [15:0] WR_ROWS = 16'hefff;
	wire [15:0] row_r = row_match & RD_ROWS;
	wire [15:0] row_w = (row_match & WR_ROWS) & {16 {~cs_wr_n}};
	assign addr_rd = row_r & {16 {~pre_s01}};
	wire [7:0] d_r = ~read_bus_n;
	wire pad_disable = pre_s01 | ~cs_rd;
	wire [7:0] pad_oe;
	genvar _gv_b_2;
	generate
		for (_gv_b_2 = 0; _gv_b_2 < 8; _gv_b_2 = _gv_b_2 + 1) begin : g_pad
			localparam b = _gv_b_2;
			pokey_cell7 u_pad(
				.in(d_r[b]),
				.disable_n(pad_disable),
				.out(d_out[b]),
				.oe(pad_oe[b])
			);
		end
	endgenerate
	assign d_oe = &pad_oe;
	wire wr_open = phi2b & ~pre_s01;
	reg [7:0] wdata_hold;
	always @(posedge clk)
		if (wr_open)
			wdata_hold <= d_in;
	assign write_data = wdata_hold;
	reg [15:0] row_w_hold;
	always @(posedge clk)
		if (wr_open)
			row_w_hold <= row_w;
	wire [15:0] wr_q;
	wire [15:0] wr_qn;
	pokey_cell22 #(.OPTION1(1'b1)) u_wF(
		.in(row_w_hold[4'hf]),
		.c(phi2b),
		.q(wr_q[4'hf]),
		.q_n(wr_qn[4'hf])
	);
	pokey_cell22 u_wE(
		.in(row_w_hold[4'he]),
		.c(phi2b),
		.q(wr_q[4'he]),
		.q_n(wr_qn[4'he])
	);
	pokey_cell22 u_wD(
		.in(row_w_hold[4'hd]),
		.c(phi2b),
		.q(wr_q[4'hd]),
		.q_n(wr_qn[4'hd])
	);
	pokey_cell22 u_wB(
		.in(row_w_hold[4'hb]),
		.c(phi2b),
		.q(wr_q[4'hb]),
		.q_n(wr_qn[4'hb])
	);
	pokey_cell21 u_wA(
		.in(row_w_hold[4'ha]),
		.c(phi2b),
		.q(wr_q[4'ha])
	);
	pokey_cell21 u_w9(
		.in(row_w_hold[4'h9]),
		.c(phi2b),
		.q(wr_q[4'h9])
	);
	pokey_cell22 #(.OPTION1(1'b1)) u_w8(
		.in(row_w_hold[4'h8]),
		.c(phi2b),
		.q(wr_q[4'h8]),
		.q_n(wr_qn[4'h8])
	);
	pokey_cell22 u_w7(
		.in(row_w_hold[4'h7]),
		.c(phi2b),
		.q(wr_q[4'h7]),
		.q_n(wr_qn[4'h7])
	);
	pokey_cell22 u_w6(
		.in(row_w_hold[4'h6]),
		.c(phi2b),
		.q(wr_q[4'h6]),
		.q_n(wr_qn[4'h6])
	);
	pokey_cell22 u_w5(
		.in(row_w_hold[4'h5]),
		.c(phi2b),
		.q(wr_q[4'h5]),
		.q_n(wr_qn[4'h5])
	);
	pokey_cell22 u_w4(
		.in(row_w_hold[4'h4]),
		.c(phi2b),
		.q(wr_q[4'h4]),
		.q_n(wr_qn[4'h4])
	);
	pokey_cell22 u_w3(
		.in(row_w_hold[4'h3]),
		.c(phi2b),
		.q(wr_q[4'h3]),
		.q_n(wr_qn[4'h3])
	);
	pokey_cell22 u_w2(
		.in(row_w_hold[4'h2]),
		.c(phi2b),
		.q(wr_q[4'h2]),
		.q_n(wr_qn[4'h2])
	);
	pokey_cell22 u_w1(
		.in(row_w_hold[4'h1]),
		.c(phi2b),
		.q(wr_q[4'h1]),
		.q_n(wr_qn[4'h1])
	);
	pokey_cell22 u_w0(
		.in(row_w_hold[4'h0]),
		.c(phi2b),
		.q(wr_q[4'h0]),
		.q_n(wr_qn[4'h0])
	);
	assign wr_q[4'hc] = 1'b0;
	assign wr_qn[4'hc] = 1'b1;
	assign wr_qn[4'ha] = 1'b1;
	assign wr_qn[4'h9] = 1'b1;
	assign addr_wr = wr_q;
	assign addr_wr_n = wr_qn;
	assign stimer_strobe = wr_q[4'h9];
	assign skres_strobe = wr_q[4'ha];
	assign potgo_strobe = wr_q[4'hb];
	initial _sv2v_0 = 0;
endmodule
module pokey_cell1 (
