	output wire [WIDTH - 1:0] q;
	reg [WIDTH - 1:0] hold;
	always @(posedge clk)
		if (ld)
			hold <= d;
	assign q = hold;
endmodule
module pokey_cell6 (
	clk,
	t_in,
	r,
	q,
	q_n,
	t_out
);
	input wire clk;
	input wire t_in;
	input wire r;
	output wire q;
	output wire q_n;
	output wire t_out;
	reg state;
	always @(posedge clk)
		if (r)
			state <= 1'b0;
		else if (t_in)
			state <= ~state;
	assign q = state;
	assign q_n = ~state;
	assign t_out = t_in & ~state;
endmodule
module pokey_cell7 (
	in,
	disable_n,
	out,
	oe
);
	parameter signed [31:0] WIDTH = 1;
	input wire [WIDTH - 1:0] in;
	input wire disable_n;
	output wire [WIDTH - 1:0] out;
	output wire oe;
	assign out = in;
	assign oe = ~disable_n;
endmodule
module pokey_cell8 (
	clk,
	ld,
	d,
	rd,
	rd_k,
	q,
	q_oe,
	state
);
	parameter signed [31:0] WIDTH = 1;
	input wire clk;
	input wire ld;
	input wire [WIDTH - 1:0] d;
	input wire rd;
	input wire rd_k;
	output wire [WIDTH - 1:0] q;
	output wire q_oe;
	output wire [WIDTH - 1:0] state;
	reg [WIDTH - 1:0] hold;
	always @(posedge clk)
		if (ld)
			hold <= d;
	assign state = hold;
	assign q = (rd_k ? {WIDTH {ld}} : hold);
	assign q_oe = rd | rd_k;
endmodule
module pokey_cell9 (
	in,
	rd,
	q_n,
	q_oe
);
	input wire in;
	input wire rd;
	output wire q_n;
	output wire q_oe;
	assign q_n = ~in;
	assign q_oe = rd;
endmodule
module pokey_chan (
	clk,
	wr_en,
	audc_wr,
	write_data,
	count_en,
	clk179_en,
	ph2_en,
	wide_lo,
	force_reload,
	pulse_mask,
	reload_delay,
	poly4,
	poly5,
	poly17,
	stimer,
	stimer_level,
	hp_clock,
	hp_enable,
	borrow,
	borrow_raw,
	out,
	dac
);
	input wire clk;
	input wire wr_en;
	input wire audc_wr;
	input wire [7:0] write_data;
	input wire count_en;
	input wire clk179_en;
	input wire ph2_en;
	input wire wide_lo;
	input wire force_reload;
	input wire pulse_mask;
	input wire [2:0] reload_delay;
	input wire poly4;
	input wire poly5;
	input wire poly17;
	input wire stimer;
	input wire stimer_level;
	input wire hp_clock;
	input wire hp_enable;
	output wire borrow;
	output wire borrow_raw;
	output wire out;
	output wire [3:0] dac;
	wire [7:4] audc_ctl;
	wire [3:0] vol_n;
	pokey_cell5 #(.WIDTH(4)) u_audc_ctl(
		.clk(clk),
		.ld(audc_wr),
		.d(write_data[7:4]),
		.q(audc_ctl)
	);
	pokey_cell12 #(.WIDTH(4)) u_audc_vol(
		.clk(clk),
		.ld(audc_wr),
		.d(write_data[3:0]),
		.q_n(vol_n)
	);
	wire [3:0] vol = ~vol_n;
	wire vol_only = audc_ctl[4];
	wire pure_tone = audc_ctl[5];
	wire use_poly4 = audc_ctl[6];
	wire notpoly5 = audc_ctl[7];
	localparam [7:0] CELL20 = 8'b00010001;
	wire [7:0] count;
	wire [7:0] bor;
	wire [7:0] cr;
	wire reload_i;
	reg [2:0] delay_q;
	wire holding = delay_q != 3'd0;
	genvar _gv_i_4;
	generate
		for (_gv_i_4 = 0; _gv_i_4 < 8; _gv_i_4 = _gv_i_4 + 1) begin : g_audf
			localparam i = _gv_i_4;
			if (i == 0) begin : g_clk
				assign cr[i] = count_en & ~holding;
			end
			else begin : g_ripple
				assign cr[i] = bor[i - 1];
			end
			if (CELL20[i]) begin : g_cell20
				pokey_cell20 u(
					.clk(clk),
					.wr(wr_en),
					.d(write_data[i]),
					.ld(reload_i),
					.cr(cr[i]),
					.q(count[i]),
					.reload(),
					.bor(bor[i]),
					.bor_n()
				);
			end
			else begin : g_cell24
				pokey_cell24 #(.OPTION1(i == 7)) u(
					.clk(clk),
					.wr(wr_en),
					.d(write_data[i]),
					.ld(reload_i),
					.cr(cr[i]),
					.q(count[i]),
					.reload(),
					.bor(bor[i]),
					.bor_n()
				);
			end
		end
	endgenerate
	wire tick_raw = bor[7];
	wire tick = tick_raw & ~pulse_mask;
	assign borrow = tick;
	assign borrow_raw = tick_raw;
	reg ld_q;
	always @(posedge clk) ld_q <= (stimer | force_reload) | (tick_raw & ~wide_lo);
	assign reload_i = ld_q;
	always @(posedge clk)
		if (stimer)
			delay_q <= 3'd0;
		else if (reload_i)
			delay_q <= reload_delay;
		else if (clk179_en && holding)
			delay_q <= delay_q - 3'd1;
	reg tick_win;
	always @(posedge clk)
		if (tick)
			tick_win <= 1'b1;
		else if (clk179_en)
			tick_win <= 1'b0;
	wire poly5_gate;
	pokey_cell2 u_poly5_gate(
		.clk(clk),
		.ld(tick | tick_win),
		.d(~poly5),
		.p(1'b0),
		.r(notpoly5),
		.q(poly5_gate)
	);
	wire allow = ~poly5_gate;
	reg tick_d;
	reg poly4_s;
	reg poly17_s;
	always @(posedge clk) begin
		tick_d <= tick;
		if (tick) begin
			poly4_s <= poly4;
			poly17_s <= poly17;
		end
	end
	reg wave_q;
	always @(posedge clk)
		if (stimer)
			wave_q <= stimer_level;
		else if (tick_d && allow) begin
			if (pure_tone)
				wave_q <= ~wave_q;
			else if (use_poly4)
				wave_q <= poly4_s;
			else
				wave_q <= poly17_s;
		end
	assign out = wave_q;
	reg hp_q;
	reg hp_pend;
	always @(posedge clk) begin
		if (hp_clock)
			hp_pend <= 1'b1;
		else if (ph2_en)
			hp_pend <= 1'b0;
		if (!hp_enable)
			hp_q <= 1'b0;
		else if (hp_pend && ph2_en)
			hp_q <= wave_q;
	end
	wire filtered = wave_q ^ hp_q;
	pokey_cell11 u_dac(
		.vol(vol),
		.vol_only(vol_only),
		.in(filtered),
		.out(dac)
	);
endmodule
module pokey_clkdiv (
	clk,
	phi2_en,
	init,
	clk179_en,
	clk64_en,
	clk15_en
);
	input wire clk;
	input wire phi2_en;
	input wire init;
	output wire clk179_en;
	output reg clk64_en;
	output reg clk15_en;
	assign clk179_en = phi2_en;
	reg [4:0] m = 5'b11111;
	wire cmp64 = m == 5'b00010;
	wire fb64 = m[2] ^ m[4];
	wire new64 = (init | cmp64) | fb64;
	reg [6:0] n = 7'b0000000;
	wire cmp15 = n == 7'b1001001;
	wire fb15 = ~(n[5] ^ n[6]);
	wire new15 = ~init & (cmp15 | fb15);
	always @(posedge clk) begin
		clk64_en <= 1'b0;
		clk15_en <= 1'b0;
		if (phi2_en) begin
			m <= {m[3:0], new64};
			n <= {n[5:0], new15};
			clk64_en <= cmp64;
			clk15_en <= cmp15;
		end
	end
endmodule
module pokey_clkgen (
	clk,
	ph1_en,
	ph2_en,
	phi1,
	phi2,
	phi2b,
	pre_s01
);
	input wire clk;
	input wire ph1_en;
	input wire ph2_en;
	output wire phi1;
	output wire phi2;
	output wire phi2b;
	output wire pre_s01;
	assign phi1 = ph1_en;
	assign phi2 = ph2_en;
	reg phi2b_q;
	always @(posedge clk)
		if (ph2_en)
			phi2b_q <= 1'b1;
		else if (ph1_en)
			phi2b_q <= 1'b0;
	assign phi2b = phi2b_q;
	reg pre_s01_q;
	always @(posedge clk)
		if (ph1_en)
			pre_s01_q <= 1'b1;
		else if (ph2_en)
			pre_s01_q <= 1'b0;
	assign pre_s01 = pre_s01_q | ph1_en;
endmodule
module pokey_irq (
	clk,
	irqen_wr,
	skctl_wr,
	irqst_rd,
	skstat_rd,
	skres,
	write_data,
	timer1,
	timer2,
	timer4,
	break_key,
	other_key,
	serin_ready,
	serout_needed,
	serout_done,
	frame_error,
	kbd_overrun,
	sid_pad,
	shift_key,
	key_down,
	serin_busy,
	irqst,
	skstat,
	skctl,
	init_mode,
	irq_n_out,
	irq_oe
);
	input wire clk;
	input wire irqen_wr;
	input wire skctl_wr;
	input wire irqst_rd;
	input wire skstat_rd;
	input wire skres;
	input wire [7:0] write_data;
	input wire timer1;
	input wire timer2;
	input wire timer4;
	input wire break_key;
	input wire other_key;
	input wire serin_ready;
	input wire serout_needed;
	input wire serout_done;
	input wire frame_error;
	input wire kbd_overrun;
	input wire sid_pad;
	input wire shift_key;
	input wire key_down;
	input wire serin_busy;
	output wire [7:0] irqst;
	output wire [7:0] skstat;
	output wire [7:0] skctl;
	output wire init_mode;
	output wire irq_n_out;
	output wire irq_oe;
	wire [7:0] irqen_n;
	pokey_cell12 #(.WIDTH(8)) u_irqen(
		.clk(clk),
		.ld(irqen_wr),
		.d(write_data),
		.q_n(irqen_n)
	);
	wire [7:0] set_src = {break_key, other_key, serin_ready, serout_needed, serout_done, timer4, timer2, timer1};
	reg [7:0] pend;
	always @(posedge clk) pend <= set_src | (pend & ~irqen_n);
	wire [7:0] pend_eff = {pend[7:4], set_src[3], pend[2:0]};
	wire [7:0] irq_assert = pend_eff & ~irqen_n;
	wire [7:0] irqst_q;
	wire [7:0] irqst_oe;
	genvar _gv_i_5;
	generate
		for (_gv_i_5 = 0; _gv_i_5 < 8; _gv_i_5 = _gv_i_5 + 1) begin : g_irqst
			localparam i = _gv_i_5;
			pokey_cell9 u(
				.in(irq_assert[i]),
				.rd(irqst_rd),
				.q_n(irqst_q[i]),
				.q_oe(irqst_oe[i])
			);
		end
	endgenerate
	assign irqst = irqst_q | ~irqst_oe;
	assign irq_n_out = 1'b0;
	assign irq_oe = |irq_assert;
	wire [7:0] skctl_q;
	pokey_cell5 #(.WIDTH(8)) u_skctl(
		.clk(clk),
		.ld(skctl_wr),
		.d(write_data),
		.q(skctl_q)
	);
	assign skctl = skctl_q;
	assign init_mode = ~(skctl_q[1] | skctl_q[0]);
	wire key_ovrun = kbd_overrun | (other_key & irq_assert[6]);
	wire ser_ovrun = serin_ready & irq_assert[5];
	reg lat_frame;
	reg lat_kbd_ovr;
	reg lat_ser_ovr;
	always @(posedge clk)
		if (skres) begin
			lat_frame <= 1'b1;
			lat_kbd_ovr <= 1'b1;
			lat_ser_ovr <= 1'b1;
		end
		else begin
			if (frame_error)
				lat_frame <= 1'b0;
			if (key_ovrun)
				lat_kbd_ovr <= 1'b0;
			if (ser_ovrun)
				lat_ser_ovr <= 1'b0;
		end
	wire [7:1] skstat_in = {~lat_frame, ~lat_kbd_ovr, ~lat_ser_ovr, ~sid_pad, shift_key, key_down, serin_busy};
	wire [7:1] skstat_q;
	wire [7:1] skstat_oe;
	generate
		for (_gv_i_5 = 1; _gv_i_5 < 8; _gv_i_5 = _gv_i_5 + 1) begin : g_skstat
			localparam i = _gv_i_5;
			pokey_cell9 u(
				.in(skstat_in[i]),
				.rd(skstat_rd),
				.q_n(skstat_q[i]),
				.q_oe(skstat_oe[i])
			);
		end
	endgenerate
	assign skstat[7:1] = skstat_q | ~skstat_oe;
	assign skstat[0] = 1'b1;
endmodule
module pokey_kbd (
	clk,
	scan_en,
	kbd_enable,
	debounce_en,
	init,
	kr1,
	kr2,
	kbcode_rd,
	k,
	kbcode,
	kbcode_bus,
	key_down,
	shift_key,
	break_key,
	other_key,
	kbd_overrun
);
	input wire clk;
	input wire scan_en;
	input wire kbd_enable;
	input wire debounce_en;
	input wire init;
	input wire kr1;
	input wire kr2;
	input wire kbcode_rd;
	output wire [5:0] k;
	output wire [7:0] kbcode;
	output wire [7:0] kbcode_bus;
	output wire key_down;
	output wire shift_key;
	output wire break_key;
	output wire other_key;
	output wire kbd_overrun;
	wire kb_scan_dis = ~kbd_enable | init;
	wire ikr1 = ~kr1;
	wire ikr2 = ~kr2;
	wire [5:0] cnt;
	wire [5:0] cnt_n;
	wire [6:0] tchain;
	assign tchain[0] = scan_en;
	genvar _gv_i_6;
	generate
		for (_gv_i_6 = 0; _gv_i_6 < 6; _gv_i_6 = _gv_i_6 + 1) begin : g_scan
			localparam i = _gv_i_6;
			if ((i % 2) == 0) begin : g_type1
				pokey_cell3 u(
					.clk(clk),
					.t_in(tchain[i]),
					.r(kb_scan_dis),
					.q(cnt[i]),
					.q_n(cnt_n[i]),
					.t_out(tchain[i + 1])
				);
			end
			else begin : g_type2
				pokey_cell6 u(
					.clk(clk),
					.t_in(tchain[i]),
					.r(kb_scan_dis),
					.q(cnt[i]),
					.q_n(cnt_n[i]),
					.t_out(tchain[i + 1])
				);
			end
		end
	endgenerate
	assign k = cnt_n;
	wire kb_cmp_ld;
	wire [5:0] cmp_q;
	wire [5:0] cmp_match;
	generate
		for (_gv_i_6 = 0; _gv_i_6 < 6; _gv_i_6 = _gv_i_6 + 1) begin : g_cmp
			localparam i = _gv_i_6;
			pokey_cell4 u(
				.clk(clk),
				.ld(kb_cmp_ld),
				.d(cnt[i]),
				.q(cmp_q[i]),
				.match(cmp_match[i])
			);
		end
	endgenerate
	wire c_match = &cmp_match;
	wire deb_comp = ~(~debounce_en | c_match);
	wire key_q0;
	wire key_q1;
	wire pt1 = ikr1 & ~deb_comp;
	wire pt2 = (~key_q0 & ~key_q1) & deb_comp;
	wire pt3 = ~key_q1 & deb_comp;
	wire pt4 = ~key_q0 & ~key_q1;
	wire pt5 = ikr1 & ~key_q1;
	wire pt6 = ((ikr1 & ~key_q0) & key_q1) & ~deb_comp;
	wire pt7 = (ikr1 & key_q0) & key_q1;
	wire pt8 = (~ikr1 & ~key_q0) & deb_comp;
	wire key_d0 = ~(((pt1 | pt2) | pt7) | pt8);
	wire key_d1 = ~(((pt3 | pt4) | pt5) | pt6);
	wire n_ld_comp = ~pt7;
	wire n_ld_kbus = ~pt6;
	pokey_cell2 u_keyq0(
		.clk(clk),
		.ld(scan_en),
		.d(key_d0),
		.p(kb_scan_dis),
		.r(1'b0),
		.q(key_q0)
	);
	pokey_cell2 u_keyq1(
		.clk(clk),
		.ld(scan_en),
		.d(key_d1),
		.p(kb_scan_dis),
		.r(1'b0),
		.q(key_q1)
	);
	assign kb_cmp_ld = scan_en & ~n_ld_comp;
	reg kbcode_ld;
	always @(posedge clk) kbcode_ld <= scan_en & ~n_ld_kbus;
	wire ctrl_q;
	wire shift_q;
	wire kbcode_oe;
	pokey_cell1 #(.WIDTH(8)) u_kbcode(
		.clk(clk),
		.ld(kbcode_ld),
		.d({ctrl_q, shift_q, cmp_q}),
		.rd(kbcode_rd),
		.q(kbcode),
		.q_oe(kbcode_oe),
		.state()
	);
	assign kbcode_bus = (kbcode_oe ? kbcode : 8'hff);
	wire at_ctrl = scan_en & (cnt == 6'h00);
	wire at_shift = scan_en & (cnt == 6'h10);
	wire at_break = scan_en & (cnt == 6'h30);
	pokey_cell2 u_ctrl(
		.clk(clk),
		.ld(at_ctrl),
		.d(ikr2),
		.p(1'b0),
		.r(1'b0),
		.q(ctrl_q)
	);
	pokey_cell2 u_shift(
		.clk(clk),
		.ld(at_shift),
		.d(ikr2),
		.p(1'b0),
		.r(1'b0),
		.q(shift_q)
	);
	reg break_n;
	reg break_n_q;
	always @(posedge clk) begin
		break_n_q <= break_n;
		if (at_break)
			break_n <= ~ikr2;
	end
	wire pre_break = break_n_q & ~break_n;
	assign key_down = ~key_q1;
	assign shift_key = shift_q;
	assign break_key = pre_break;
	assign other_key = kbcode_ld;
	assign kbd_overrun = 1'b0;
endmodule
module pokey_mixer (
	dac1,
	dac2,
	dac3,
	dac4,
	aud
);
	input wire [3:0] dac1;
	input wire [3:0] dac2;
	input wire [3:0] dac3;
	input wire [3:0] dac4;
	output wire [15:0] aud;
	function automatic [7:0] weigh;
		input reg [3:0] d;
		weigh = (((d[0] ? 8'd12 : 8'd0) + (d[1] ? 8'd26 : 8'd0)) + (d[2] ? 8'd56 : 8'd0)) + (d[3] ? 8'd112 : 8'd0);
	endfunction
	wire [9:0] raw = (({2'b00, weigh(dac1)} + {2'b00, weigh(dac2)}) + {2'b00, weigh(dac3)}) + {2'b00, weigh(dac4)};
	function automatic [15:0] curve;
		input reg [4:0] i;
		case (i)
			5'd0: curve = 16'd0;
			5'd1: curve = 16'd5525;
			5'd2: curve = 16'd11051;
			5'd3: curve = 16'd16576;
			5'd4: curve = 16'd22054;
			5'd5: curve = 16'd27061;
			5'd6: curve = 16'd31543;
			5'd7: curve = 16'd35556;
			5'd8: curve = 16'd39148;
			5'd9: curve = 16'd42364;
			5'd10: curve = 16'd45242;
			5'd11: curve = 16'd47820;
			5'd12: curve = 16'd50127;
			5'd13: curve = 16'd52192;
			5'd14: curve = 16'd54041;
			5'd15: curve = 16'd55697;
			5'd16: curve = 16'd57179;
			5'd17: curve = 16'd58505;
			5'd18: curve = 16'd59693;
			5'd19: curve = 16'd60756;
			5'd20: curve = 16'd61708;
			5'd21: curve = 16'd62560;
			5'd22: curve = 16'd63323;
			5'd23: curve = 16'd64006;
			5'd24: curve = 16'd64617;
			5'd25: curve = 16'd65164;
			5'd26: curve = 16'd65535;
			default: curve = 16'd65535;
		endcase
	endfunction
	wire [4:0] seg = raw[9:5];
	wire [4:0] frac = raw[4:0];
	wire [15:0] lo = curve(seg);
	wire [15:0] hi = curve(seg + 5'd1);
	wire [12:0] span = hi[12:0] - lo[12:0];
	wire [17:0] step = span * {8'd0, frac};
	assign aud = lo + {3'd0, step[17:5]};
endmodule
module pokey_poly (
	clk,
	poly_en,
	init,
	poly9_sel,
	random_rd,
	poly4_out,
	poly5_out,
	poly17_out,
	random
);
	input wire clk;
	input wire poly_en;
	input wire init;
	input wire poly9_sel;
	input wire random_rd;
	output wire poly4_out;
	output wire poly5_out;
	output wire poly17_out;
	output wire [7:0] random;
	reg [3:0] poly4;
	always @(posedge clk)
		if (init)
			poly4 <= 4'h0;
		else if (poly_en)
			poly4 <= {poly4[2:0], ~(poly4[2] ^ poly4[3])};
	assign poly4_out = poly4[3];
	reg [4:0] poly5;
	always @(posedge clk)
		if (init)
			poly5 <= 5'h00;
		else if (poly_en)
			poly5 <= {poly5[3:0], ~(poly5[2] ^ poly5[4])};
	assign poly5_out = poly5[4];
	reg [16:0] shift;
	reg cycle_delay;
	reg sel9_del;
	wire feedback = ~(shift[13] ^ shift[8]);
	reg init_q;
	always @(posedge clk) init_q <= init;
	always @(posedge clk)
