	assign core_phi2_en = phi2_en & ~bus_off;
	reg phase2;
	always @(posedge clk_sys)
		if (phi1_en)
			phase2 <= 1'b0;
		else if (phi2_en)
			phase2 <= 1'b1;
	assign phi1_out = ~phase2;
	assign phi2_out = phase2;
	mos6502 #(.BCD_EN(1'b1)) core(
		.clk_sys(clk_sys),
		.phi1_en(core_phi1_en),
		.phi2_en(core_phi2_en),
		.res_n(res_n),
		.rdy(rdy),
		.irq_n(irq_n),
		.nmi_n(nmi_n),
		.so_n(so_n),
		.data_in(data_in),
		.data_out(data_out),
		.data_oe(core_data_oe),
		.addr_out(addr_out),
		.rw_n(rw_n),
		.sync(sync),
		.phi1_out(),
		.phi2_out(),
		.jammed(jammed),
		.dbg_a(dbg_a),
		.dbg_x(dbg_x),
		.dbg_y(dbg_y),
		.dbg_s(dbg_s),
		.dbg_p(dbg_p),
		.dbg_ir(dbg_ir),
		.dbg_pc(dbg_pc),
		.dbg_t(),
		.dbg_hold(),
		.dbg_int_active(),
		.dbg_take_int(),
		.dbg_res_active(),
		.dbg_tg()
	);
endmodule
